<?php
namespace Pterodactyl\Http\Controllers\Admin;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Pterodactyl\Http\Controllers\Controller;
class MarketingController extends Controller { public function index(){return view('admin.commerce.marketing',['announcements'=>DB::table('announcements')->orderByDesc('id')->get(),'discounts'=>DB::table('discount_codes')->orderByDesc('id')->get(),'products'=>DB::table('billing_products')->orderBy('name')->get()]);} public function announcementStore(Request $r){$d=$r->validate(['title'=>'required|string|max:160','message'=>'required|string|max:2000','type'=>'required|in:info,success,warning,danger','button_text'=>'nullable|string|max:80','button_url'=>'nullable|url|max:500','starts_at'=>'nullable|date','ends_at'=>'nullable|date|after:starts_at']);DB::table('announcements')->insert(array_merge($d,['active'=>$r->boolean('active'),'created_at'=>now(),'updated_at'=>now()]));return back()->with('success','Announcement blev oprettet.');} public function announcementUpdate(Request $r,int $id){$d=$r->validate(['title'=>'required|string|max:160','message'=>'required|string|max:2000','type'=>'required|in:info,success,warning,danger','button_text'=>'nullable|string|max:80','button_url'=>'nullable|url|max:500','starts_at'=>'nullable|date','ends_at'=>'nullable|date|after:starts_at']);DB::table('announcements')->where('id',$id)->update(array_merge($d,['active'=>$r->boolean('active'),'updated_at'=>now()]));return back()->with('success','Announcement blev gemt.');} public function announcementDelete(int $id){DB::table('announcements')->where('id',$id)->delete();return back()->with('success','Announcement blev slettet.');} public function discountStore(Request $r){$d=$this->discountData($r);$id=DB::table('discount_codes')->insertGetId(array_merge($d,['created_at'=>now(),'updated_at'=>now()]));$this->syncProducts($id,$r);return back()->with('success','Rabatkoden blev oprettet.');} public function discountUpdate(Request $r,int $id){$d=$this->discountData($r,$id);DB::table('discount_codes')->where('id',$id)->update(array_merge($d,['updated_at'=>now()]));$this->syncProducts($id,$r);return back()->with('success','Rabatkoden blev gemt.');} public function discountDelete(int $id){DB::transaction(function()use($id){DB::table('discount_code_products')->where('discount_code_id',$id)->delete();DB::table('discount_codes')->where('id',$id)->delete();});return back()->with('success','Rabatkoden blev slettet.');} private function discountData(Request $r,?int $id=null):array{$d=$r->validate(['code'=>'required|string|max:80','name'=>'required|string|max:160','type'=>'required|in:percent,fixed','value'=>'required|numeric|min:0.01|max:999999','minimum_amount'=>'nullable|numeric|min:0','maximum_discount'=>'nullable|numeric|min:0','usage_limit'=>'nullable|integer|min:1','per_user_limit'=>'nullable|integer|min:1','starts_at'=>'nullable|date','ends_at'=>'nullable|date|after:starts_at']);$code=strtoupper(trim($d['code']));$exists=DB::table('discount_codes')->where('code',$code)->when($id,fn($q)=>$q->where('id','!=',$id))->exists();if($exists)abort(422,'Rabatkoden findes allerede.');if($d['type']==='percent'&&(float)$d['value']>100)abort(422,'Procentrabat kan højst være 100%.');$d['code']=$code;$d['active']=$r->boolean('active');$d['new_customers_only']=$r->boolean('new_customers_only');return $d;} private function syncProducts(int $id,Request $r):void{DB::table('discount_code_products')->where('discount_code_id',$id)->delete();foreach(array_unique(array_map('intval',$r->input('products',[]))) as $pid)if($pid>0)DB::table('discount_code_products')->insert(['discount_code_id'=>$id,'product_id'=>$pid]);} }